// Turns a compiled policy back into plain English. The owner confirms a policy by reading
// this text, which is generated by code from the exact JSON that will be enforced, so what
// they read is what runs, whatever the policy compiler intended.

import { CATEGORY_LABELS, type Category, type Policy } from "@/lib/domain/schemas";
import { formatUsd } from "@/lib/money";

const PERIOD: Record<Policy["budget"]["period"], string> = { day: "24 hours", week: "7 days", month: "30 days" };
const APPROVER: Record<Policy["approval"]["approver"], string> = {
  owner: "the owner",
  guardian: "the guardian",
  owner_and_guardian: "both the owner and the guardian",
};

const list = (categories: Category[]) => categories.map((c) => CATEGORY_LABELS[c]).join(", ");
const pad = (n: number) => n.toString().padStart(2, "0");

export function describePolicy(policy: Policy): string[] {
  const lines: string[] = [];

  lines.push(`Spend up to ${formatUsd(policy.budget.limitCents)} in any ${PERIOD[policy.budget.period]}.`);

  const max = `Never more than ${formatUsd(policy.perPayment.maxCents)} in one payment`;
  lines.push(
    policy.perPayment.askAboveCents === null
      ? `${max}.`
      : `${max}; anything over ${formatUsd(policy.perPayment.askAboveCents)} needs approval.`,
  );

  if (policy.categories.blocked.length > 0) lines.push(`Never buy: ${list(policy.categories.blocked)}.`);
  if (policy.blockCashEquivalents) lines.push("Gift cards, prepaid cards and crypto are blocked, because they work like cash.");
  if (policy.categories.askFor.length > 0) lines.push(`Always ask first for: ${list(policy.categories.askFor)}.`);
  if (policy.categories.allowedOnly) {
    lines.push(`Without asking, only: ${list(policy.categories.allowedOnly)}. Anything else needs approval.`);
  }

  if (policy.merchants.blocked.length > 0) lines.push(`Never pay: ${policy.merchants.blocked.join(", ")}.`);
  if (policy.merchants.allowedOnly) lines.push(`Without asking, only these merchants: ${policy.merchants.allowedOnly.join(", ")}.`);

  lines.push(
    {
      allow: "Paying a merchant or person for the first time is allowed.",
      ask: "The first payment to a new merchant or person needs approval.",
      block: "Payments to merchants or people who haven't been paid before are blocked.",
    }[policy.newPayee.action],
  );

  if (!policy.transfers.enabled) lines.push("Sending money to people is not allowed.");
  else if (policy.transfers.askAboveCents !== null) {
    lines.push(`Sending money to people is allowed; over ${formatUsd(policy.transfers.askAboveCents)} needs approval.`);
  } else lines.push("Sending money to people is allowed within the limits above.");

  if (policy.velocity) {
    lines.push(`More than ${policy.velocity.maxPayments} payments in ${policy.velocity.windowMinutes} minutes needs approval.`);
  }
  if (policy.quietHours) {
    const { startHour, endHour, timezone } = policy.quietHours;
    lines.push(`Between ${pad(startHour)}:00 and ${pad(endHour)}:00 (${timezone}), every payment needs approval.`);
  }
  if (policy.requireMandate) lines.push("Every purchase must belong to a task the owner gave the agent.");

  lines.push(`Held payments are approved by ${APPROVER[policy.approval.approver]}.`);
  if (policy.approval.coolingOffMinutes > 0) {
    lines.push(`A payment that looks like a scam waits ${policy.approval.coolingOffMinutes} minutes before anyone can approve it.`);
  }
  return lines;
}
